using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Services;

public sealed record OccupancyForecastRow(Guid BlockId,string Block,int Capacity,int Occupied,int ExpectedDepartures,int ForecastOccupied,decimal ForecastPercent);
public interface IHostelDepthService
{
 Task<FeeInvoice> IntegrateHostelFeeAsync(Guid hostelFeeId,CancellationToken token=default);
 Task<HostelMessBill> GenerateMessBillAsync(Guid allocationId,DateOnly from,DateOnly to,decimal rate,CancellationToken token=default);
 Task EscalateBreachedMaintenanceAsync(CancellationToken token=default);
 Task<HostelClearanceRequest> StartClearanceAsync(Guid allocationId,DateOnly vacationFrom,DateOnly? expectedReturn,bool finalCheckout,CancellationToken token=default);
 Task CompleteClearanceAsync(Guid requestId,CancellationToken token=default);
 Task<IReadOnlyList<OccupancyForecastRow>> ForecastAsync(Guid? branchId,DateOnly asOf,CancellationToken token=default);
}
public sealed class HostelDepthService(TenantDbContext db,IFinanceAccountingService finance):IHostelDepthService
{
 public async Task<FeeInvoice> IntegrateHostelFeeAsync(Guid hostelFeeId,CancellationToken token=default){var fee=await db.HostelFees.Include(x=>x.HostelAllocation).SingleAsync(x=>x.Id==hostelFeeId,token);if(fee.FeeInvoiceId.HasValue)return await db.FeeInvoices.SingleAsync(x=>x.Id==fee.FeeInvoiceId,token);var allocation=fee.HostelAllocation!;var invoice=new FeeInvoice{TenantId=fee.TenantId,BranchId=fee.BranchId,StudentProfileId=allocation.StudentProfileId,InvoiceNumber=fee.InvoiceNumber,InvoiceDate=fee.BillingMonth,DueDate=fee.DueDate,Status=fee.Status,SubTotal=fee.Amount,TotalAmount=fee.Amount,PaidAmount=fee.PaidAmount,Lines=[new(){TenantId=fee.TenantId,BranchId=fee.BranchId,Description=$"Hostel accommodation - {fee.BillingMonth:MMM yyyy}",ComponentType=FeeComponentType.Hostel,Amount=fee.Amount}]};db.FeeInvoices.Add(invoice);await db.SaveChangesAsync(token);fee.FeeInvoiceId=invoice.Id;await db.SaveChangesAsync(token);if(invoice.Status!=InvoiceStatus.Draft)await finance.PostInvoiceAsync(invoice.Id,token);return invoice;}
 public async Task<HostelMessBill> GenerateMessBillAsync(Guid allocationId,DateOnly from,DateOnly to,decimal rate,CancellationToken token=default){if(to<from)throw new InvalidOperationException("Billing period is invalid.");if(await db.HostelMessBills.AnyAsync(x=>x.HostelAllocationId==allocationId&&x.PeriodStart==from&&x.PeriodEnd==to,token))throw new InvalidOperationException("This mess period is already billed.");var allocation=await db.HostelAllocations.SingleAsync(x=>x.Id==allocationId,token);var meals=await db.HostelMessAttendances.CountAsync(x=>x.HostelAllocationId==allocationId&&x.AttendanceDate>=from&&x.AttendanceDate<=to&&(x.Status==MessAttendanceStatus.Present||x.Status==MessAttendanceStatus.Guest),token);var amount=meals*rate;var invoice=new FeeInvoice{TenantId=allocation.TenantId,BranchId=allocation.BranchId,StudentProfileId=allocation.StudentProfileId,InvoiceNumber=$"MESS-{to:yyyyMM}-{allocation.Id.ToString("N")[..6]}".ToUpperInvariant(),InvoiceDate=to,DueDate=to.AddDays(10),Status=InvoiceStatus.Issued,SubTotal=amount,TotalAmount=amount,Lines=[new(){TenantId=allocation.TenantId,BranchId=allocation.BranchId,Description=$"Mess charges {from:dd MMM} - {to:dd MMM}",ComponentType=FeeComponentType.Hostel,Amount=amount}]};var bill=new HostelMessBill{TenantId=allocation.TenantId,BranchId=allocation.BranchId,HostelAllocationId=allocationId,PeriodStart=from,PeriodEnd=to,ChargeableMeals=meals,RatePerMeal=rate,Amount=amount,FeeInvoice=invoice};db.Add(bill);await db.SaveChangesAsync(token);if(amount>0)await finance.PostInvoiceAsync(invoice.Id,token);return bill;}
 public async Task EscalateBreachedMaintenanceAsync(CancellationToken token=default){var now=DateTime.UtcNow;var breached=await db.HostelMaintenanceRequests.Where(x=>x.Status!=HostelMaintenanceStatus.Resolved&&x.Status!=HostelMaintenanceStatus.Closed&&x.Status!=HostelMaintenanceStatus.Cancelled&&x.DueOn<now).ToListAsync(token);foreach(var item in breached){if(await db.HostelMaintenanceEscalations.AnyAsync(x=>x.HostelMaintenanceRequestId==item.Id&&x.Level==item.EscalationLevel+1,token))continue;item.EscalationLevel++;db.HostelMaintenanceEscalations.Add(new(){HostelMaintenanceRequestId=item.Id,Level=item.EscalationLevel,Reason=$"SLA breached at {item.DueOn:u}."});}await db.SaveChangesAsync(token);}
 public async Task<HostelClearanceRequest> StartClearanceAsync(Guid allocationId,DateOnly vacationFrom,DateOnly? expectedReturn,bool finalCheckout,CancellationToken token=default){var allocation=await db.HostelAllocations.SingleAsync(x=>x.Id==allocationId,token);var request=new HostelClearanceRequest{TenantId=allocation.TenantId,BranchId=allocation.BranchId,HostelAllocationId=allocationId,VacationFrom=vacationFrom,ExpectedReturnOn=expectedReturn,IsFinalCheckout=finalCheckout,Items=Enum.GetValues<NoDueArea>().Select(a=>new HostelClearanceItem{TenantId=allocation.TenantId,Area=a}).ToList()};db.Add(request);await db.SaveChangesAsync(token);return request;}
 public async Task CompleteClearanceAsync(Guid requestId,CancellationToken token=default){var request=await db.HostelClearanceRequests.Include(x=>x.Items).Include(x=>x.HostelAllocation).SingleAsync(x=>x.Id==requestId,token);if(request.Items.Any(x=>!x.IsCleared))throw new InvalidOperationException("Every no-dues area must be cleared.");request.Status=HostelClearanceStatus.Completed;request.CompletedOn=DateTime.UtcNow;if(request.IsFinalCheckout){request.HostelAllocation!.Status=HostelAllocationStatus.CheckedOut;request.HostelAllocation.CheckedOutOn=request.VacationFrom;if(request.HostelAllocation.HostelBedId is Guid bedId){var bed=await db.HostelBeds.FindAsync([bedId],token);if(bed is not null)bed.Status=HostelBedStatus.Available;}}await db.SaveChangesAsync(token);}
 public async Task<IReadOnlyList<OccupancyForecastRow>> ForecastAsync(Guid? branchId,DateOnly asOf,CancellationToken token=default){var blocks=await db.HostelBlocks.Where(x=>!branchId.HasValue||x.BranchId==branchId).ToListAsync(token);var rooms=await db.HostelRooms.Where(x=>!branchId.HasValue||x.BranchId==branchId).ToListAsync(token);var allocations=await db.HostelAllocations.Where(x=>x.Status==HostelAllocationStatus.Active&&(!branchId.HasValue||x.BranchId==branchId)).ToListAsync(token);return blocks.Select(b=>{var roomIds=rooms.Where(r=>r.HostelBlockId==b.Id).Select(r=>r.Id).ToHashSet();var capacity=rooms.Where(r=>roomIds.Contains(r.Id)).Sum(r=>r.Capacity);var active=allocations.Where(a=>roomIds.Contains(a.HostelRoomId)).ToList();var leaving=active.Count(a=>a.ExpectedCheckoutOn.HasValue&&a.ExpectedCheckoutOn<=asOf);var forecast=Math.Max(0,active.Count-leaving);return new OccupancyForecastRow(b.Id,b.Name,capacity,active.Count,leaving,forecast,capacity==0?0:Math.Round(forecast*100m/capacity,2));}).ToList();}
}
